import ast, hashlib, importlib.util, json, subprocess
from pathlib import Path
root=Path('/workspace'); p=json.loads((root/'proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
def validate(x,s,path='"'$'"'):
 typ=s.get('type'); types={'object':dict,'array':list,'string':str,'boolean':bool}
 if typ in types: assert isinstance(x,types[typ]),(path,typ,type(x))
 if 'enum' in s: assert x in s['enum'],(path,x)
 if 'const' in s: assert x==s['const'],path
 if isinstance(x,str) and 'minLength' in s: assert len(x)>=s['minLength'],path
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x): validate(v,s.get('items',{}),f'{path}[{i}]')
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'missing',set(s.get('required',[]))-set(x))
  props=s.get('properties',{})
  if s.get('additionalProperties') is False: assert set(x)<=set(props),(path,'extra',set(x)-set(props))
  for k,v in x.items():
   if k in props: validate(v,props[k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
normalized=[]
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 text=(root/v['file']).read_text(); tree=ast.parse(text); compile(text,v['file'],'exec')
 config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 config=ast.literal_eval(config_node.value); assert config==v['config']
 assert not ({'epochs','batch_size','seed','train_seed','dense_learning_rate','sparse_learning_rate'} & config.keys())
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in {'torch','math','unirank'} for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in {'torch','unirank'}
 config_node.value=ast.parse('CONFIG = {}').body[0].value
 normalized.append(ast.dump(tree,include_attributes=False))
 print(v['name'],v['file'],'syntax/config OK',hashlib.sha256(text.encode()).hexdigest())
assert len(set(normalized))==1,'Variant differences beyond CONFIG'
assert {(v['config']['key_feedback'],v['config']['value_feedback']) for v in p['variants']}=={(False,False),(False,True),(True,False),(True,True)}
print('Study schema, protocol/evidence references, complete 2x2, standalone source and CONFIG-only variant differences: PASS')
print('Torch available:',importlib.util.find_spec('torch') is not None)
print('Local forward/backward/training: NOT RUN; host required')
PY"

